<?php $failed=!empty($paymentError)||($order['payment_status']??'')==='refunded';$paid=($order['payment_status']??'')==='paid';$refunded=($order['payment_status']??'')==='refunded';$cancelled=($order['status']??'')==='cancelled'; ?><section class="confirmation <?= $failed?'payment-pending':'' ?>"><span class="confirm-check"><?= $failed?'!':'✓' ?></span><p class="site-kicker"><?= $refunded?'COMMANDE REMBOURSÉE':($cancelled?'COMMANDE ANNULÉE':($failed?'PAIEMENT NON CONFIRMÉ':'COMMANDE ENREGISTRÉE')) ?></p><h1><?= $refunded?'Votre remboursement a été enregistré.':($cancelled?'Votre commande est annulée.':($failed?'Votre commande est en attente.':'Merci, votre commande est confirmée.')) ?></h1><p><?= $failed?htmlspecialchars($paymentError??'Cette commande a été remboursée.'):'La référence <strong>'.htmlspecialchars($order['reference']).'</strong> a été créée. Conservez cette page et votre référence.' ?></p><?php require __DIR__.'/../partials/payment-details.php'; ?><div class="confirm-card"><span><small>MONTANT</small><strong><?= number_format($order['total'],0,',',' ') ?> FCFA</strong></span><span><small>PAIEMENT</small><strong><?= $order['payment']==='delivery'?'À la livraison':($refunded?'Remboursé':($paid?'Déjà payé':'En attente')) ?></strong></span><span><small>STATUT</small><strong><?= htmlspecialchars($order['status']) ?></strong></span></div><?php if(!empty($order['downloads'])): ?><div class="download-library"><p class="site-kicker">VOS ACHATS NUMÉRIQUES</p><h2>Téléchargements disponibles</h2><p>Liens personnels actifs pendant 30 jours.</p><?php foreach($order['downloads'] as $download): ?><a class="digital-download" href="/commande/telecharger?token=<?= urlencode($download['token']) ?>"><span>↓</span><div><strong><?= htmlspecialchars($download['name']) ?></strong><small>PDF / livre numérique · <?= (int)$download['limit'] ?> téléchargement(s) autorisé(s)</small></div><b>Télécharger →</b></a><?php endforeach ?></div><?php endif ?><div><a class="site-btn green" href="/mon-compte">Voir mon espace</a><a class="site-btn outline" href="/">Retour à l’accueil</a></div></section><style>.payment-pending .confirm-check{background:#fff3d6;color:#9a6500}.download-library{display:block!important;text-align:left;background:#f2f7f4;border-radius:15px;padding:20px;margin:22px 0}.download-library h2{margin-bottom:4px}.download-library>p:not(.site-kicker){color:#71807b;font-size:10px}.digital-download{display:flex;align-items:center;gap:12px;background:#fff;border:1px solid #dce7e1;border-radius:12px;padding:13px;margin-top:9px}.digital-download>span{width:38px;height:38px;border-radius:10px;background:#123f3a;color:#fff;display:grid;place-items:center}.digital-download>div{display:flex;flex:1;flex-direction:column}.digital-download small{color:#7b8884;font-size:8px}.digital-download>b{font-size:9px;color:#a56e18}@media(max-width:520px){.digital-download>b{display:none}}</style>
